(4856,'San Juan de Payara',7.6464,-67.6072,null)
) v(ref, n, la, lo, pob) join public.regiones r on r.ref = v.ref
on conflict (region_id, clave) do nothing;

-- Cuentas que ya existían: departamento del profesional y lugar del último pedido del cliente
update public.perfiles pe set region_id = r.id
  from public.profesionales pr
  join public.regiones r on r.pais = 'UY' and r.nombre = pr.departamentos[1]
 where pr.id = pe.id and pe.region_id is null and pe.pais = 'UY';

do $$
begin
  if to_regclass('public.match_solicitudes') is not null then
    update public.perfiles pe set region_id = u.region_id, localidad_id = u.localidad_id
      from (select distinct on (s.cliente_id) s.cliente_id, r.id region_id,
                   (select l.id from public.localidades l where l.region_id = r.id and l.estado = 'aprobada'
                       and l.clave = public._clave_lugar(s.localidad)) localidad_id
              from public.match_solicitudes s
              join public.regiones r on r.pais = 'UY' and r.nombre = s.departamento
             order by s.cliente_id, s.creado_en desc) u
     where u.cliente_id = pe.id and pe.region_id is null and pe.pais = 'UY';
  end if;
end $$;

notify pgrst, 'reload schema';
